with remaining_keys as (select brand from products except select brand from products where brand <> 'Acme'), reconciled as (select s.* from products s inner join remaining_keys k on s.brand = k.brand) select supplier_id, stddev_samp(price) as price_stddev, bit_and(stock_qty) as stock_qty_bit_and, size(collect_set(category)) as num_categories, count_if(category = 'Fashion') as fashion_events, approx_percentile(stock_qty, array(0.25, 0.5, 0.75)) as stock_qty_quartiles from reconciled group by supplier_id order by fashion_events desc nulls first;
